# Simple CBOR encoder/decoder
import struct
def encode_cbor(obj):
    if obj is None:
        return bytes([0xF6])
    elif obj is False:
        return bytes([0xF4])
    elif obj is True:
        return bytes([0xF5])
    elif isinstance(obj, int):
        if obj >= 0:
            if obj < 24:
                return bytes([0x00 | obj])
            elif obj < 256:
                return bytes([0x18, obj])
            elif obj < 65536:
                return bytes([0x19]) + struct.pack('>H', obj)
            elif obj < 4294967296:
                return bytes([0x1A]) + struct.pack('>I', obj)
            else:
                return bytes([0x1B]) + struct.pack('>Q', obj)
        else:
            n = -1 - obj
            if n < 24:
                return bytes([0x20 | n])
            elif n < 256:
                return bytes([0x38, n])
            elif n < 65536:
                return bytes([0x39]) + struct.pack('>H', n)
            elif n < 4294967296:
                return bytes([0x3A]) + struct.pack('>I', n)
            else:
                return bytes([0x3B]) + struct.pack('>Q', n)
    elif isinstance(obj, str):
        b = obj.encode()
        ln = len(b)
        if ln < 24:
            return bytes([0x60 | ln]) + b
        elif ln < 256:
            return bytes([0x78, ln]) + b
        elif ln < 65536:
            return bytes([0x79]) + struct.pack('>H', ln) + b
        else:
            return bytes([0x7A]) + struct.pack('>I', ln) + b
    elif isinstance(obj, bytes):
        ln = len(obj)
        if ln < 24:
            return bytes([0x40 | ln]) + obj
        elif ln < 256:
            return bytes([0x58, ln]) + obj
        else:
            return bytes([0x59]) + struct.pack('>H', ln) + obj
    elif isinstance(obj, list):
        ln = len(obj)
        if ln < 24:
            hdr = bytes([0x80 | ln])
        elif ln < 256:
            hdr = bytes([0x98, ln])
        else:
            hdr = bytes([0x99]) + struct.pack('>H', ln)
        for e in obj:
            hdr += encode_cbor(e)
        return hdr
    elif isinstance(obj, dict):
        ln = len(obj)
        if ln < 24:
            hdr = bytes([0xA0 | ln])
        elif ln < 256:
            hdr = bytes([0xB8, ln])
        else:
            hdr = bytes([0xB9]) + struct.pack('>H', ln)
        for k,v in obj.items():
            hdr += encode_cbor(k)
            hdr += encode_cbor(v)
        return hdr
    elif isinstance(obj, float):
        return bytes([0xFB]) + struct.pack('>d', obj)
    else:
        raise Exception(f"unsupported {type(obj)}")

def decode_cbor(data, pos=0):
    b=data[pos]; pos+=1; major=b>>5; info=b&0x1F
    def read_arg(info,pos):
        if info<24: return info,pos
        elif info==24: return data[pos],pos+1
        elif info==25: return (data[pos]<<8|data[pos+1]),pos+2
        elif info==26: return (data[pos]<<24|data[pos+1]<<16|data[pos+2]<<8|data[pos+3]),pos+4
        elif info==27:
            v=0
            for i in range(8): v=(v<<8)|data[pos+i]
            return v,pos+8
        else: raise Exception(f"unsupported {info}")
    if major==0: val,pos=read_arg(info,pos); return val,pos
    elif major==1: val,pos=read_arg(info,pos); return -1-val,pos
    elif major==2: ln,pos=read_arg(info,pos); return data[pos:pos+ln],pos+ln
    elif major==3: ln,pos=read_arg(info,pos); return data[pos:pos+ln].decode(),pos+ln
    elif major==4:
        ln,pos=read_arg(info,pos); arr=[]
        for _ in range(ln): v,pos=decode_cbor(data,pos); arr.append(v)
        return arr,pos
    elif major==5:
        ln,pos=read_arg(info,pos); d={}
        for _ in range(ln):
            k,pos=decode_cbor(data,pos); v,pos=decode_cbor(data,pos); d[k]=v
        return d,pos
    elif major==6:
        tag,pos=read_arg(info,pos); v,pos=decode_cbor(data,pos); return (f"tag({tag})",v),pos
    elif major==7:
        if info==20: return False,pos
        elif info==21: return True,pos
        elif info==22: return None,pos
        elif info==23: return "undefined",pos
        elif info==24: return data[pos],pos+1
        elif info==25: return f"half:{data[pos:pos+2].hex()}",pos+2
        elif info==26:
            import struct; return struct.unpack('>f',data[pos:pos+4])[0],pos+4
        elif info==27:
            import struct; return struct.unpack('>d',data[pos:pos+8])[0],pos+8
        elif info==31: return "break",pos
        else: raise Exception(f"major7 {info}")

