fn handle_help(sub_m: &clap::ArgMatches, args: &[String], prog: &str) -> Result<u8, u8> {
    if let Some(cmds) = sub_m.get_many::<String>("COMMAND") {
        let cmds: Vec<&String> = cmds.collect();
        if cmds.is_empty() {
            print!("{}", include_str!("../help/main_long.txt").replace("executable", prog));
            return Ok(0);
        } else if cmds.len() == 1 {
            let c = cmds[0].as_str();
            let norm = match c {
                "rm" => "remove",
                "fo" => "follow",
                "re" => "restart",
                "cleanup" | "clear" => "clean",
                _ => c,
            };
            // Check if valid subcommand
            let valid = ["add","remove","switch","stash","enqueue","start","restart","pause","kill","send","edit","env","group","status","log","follow","wait","clean","reset","shutdown","parallel","completions","help"];
            if !valid.contains(&norm) && !["rm","fo","re","cleanup","clear"].contains(&c) {
                eprint!("error: unrecognized subcommand '{}'\n\nUsage: {} [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.\n", c, prog);
                return Err(2);
            }
            // For help <cmd>, show long help for that cmd (like --help)
            let txt = match norm {
                "add" => include_str!("../help/add_long.txt"),
                "remove" => include_str!("../help/remove_long.txt"),
                "switch" => include_str!("../help/switch_long.txt"),
                "stash" => include_str!("../help/stash_long.txt"),
