fn handle_help(sub_m: &clap::ArgMatches, args: &[String], prog: &str) -> Result<u8, u8> {
    if let Some(cmds) = sub_m.get_many::<String>("COMMAND") {
        let cmds: Vec<&String> = cmds.collect();
        if cmds.is_empty() {
            print!("{}", include_str!("../help/main_long.txt").replace("executable", prog));
            return Ok(0);
        } else if cmds.len() == 1 {
            let c = cmds[0].as_str();
            let norm = match c {
