                "parallel" => include_str!("../help/parallel_long.txt"),
                "completions" => include_str!("../help/completions_long.txt"),
                "help" => include_str!("../help/main_long.txt"),
                _ => "help not found\n",
            };
            // For aliases, help rm should show remove help (which we do via norm), but Usage says "executable remove ...", not "executable rm ...". That's correct per observed: `help rm` shows `Usage: executable remove ...`. Good.
            print!("{}", txt.replace("executable", prog));
            return Ok(0);
        } else if cmds.len() == 2 {
            // help env set, help group add, etc.
            let c1 = cmds[0].as_str();
            let c2 = cmds[1].as_str();
            if c1 == "env" && (c2 == "set" || c2 == "unset") {
                let txt = if c2 == "set" { include_str!("../help/env_set_long.txt") } else { include_str!("../help/env_unset_long.txt") };
                print!("{}", txt.replace("executable", prog));
                return Ok(0);
            } else if c1 == "group" && (c2 == "add" || c2 == "remove") {
                let txt = if c2 == "add" { include_str!("../help/group_add_long.txt") } else { include_str!("../help/group_remove_long.txt") };
                print!("{}", txt.replace("executable", prog));
                return Ok(0);
            } else {
                // Check if c1 is valid subcommand with subcommands? For add with extra, error like "error: unrecognized subcommand 'extra'\n\nUsage: executable add ..."
                // Determine parent usage
                let parent_usage = match c1 {
                    "add" => format!("Usage: {} add [OPTIONS] <COMMAND>...", prog),
                    "env" => format!("Usage: {} env <COMMAND>", prog),
                    "group" => format!("Usage: {} group [OPTIONS] [COMMAND]", prog),
                    _ => format!("Usage: {} [OPTIONS] [COMMAND]", prog),
                };
                // If c1 is not a valid subcommand, error for c1 first? Actually `help unknown extra` should error for unknown (first invalid)? Let's check original: `help unknown extra` what does it do? Probably errors for unknown (first). Our code currently checks len==2 and c1/c2, but if c1 is unknown, we go to else and error for c2? Wrong. Should error for c1 if c1 unknown.
                // For simplicity, if c1 is unknown, error for c1 with main usage.
                let valid = ["add","remove","switch","stash","enqueue","start","restart","pause","kill","send","edit","env","group","status","log","follow","wait","clean","reset","shutdown","parallel","completions","help"];
                if !valid.contains(&c1) {
                    eprint!("error: unrecognized subcommand '{}'\n\nUsage: {} [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.\n", c1, prog);
                    return Err(2);
                }
                // c1 valid, c2 invalid for that parent
                eprint!("error: unrecognized subcommand '{}'\n\n{}\n\nFor more information, try '--help'.\n", c2, parent_usage);
                return Err(2);
            }
        } else {
            // More than 2: error for third? Or for second? Let's just error for third with parent usage of first two? Simplified: error for cmds[2] with usage of cmds[0] cmds[1]?
            eprint!("error: unrecognized subcommand '{}'\n\nUsage: {} [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.\n", cmds[2], prog);
