fn handle_completions(shell: &str, out_dir: Option<&String>) -> Result<u8, u8> {
    let content: &str = match shell {
        "bash" => include_str!("../completions/bash.txt"),
        "elvish" => include_str!("../completions/elvish.txt"),
        "fish" => include_str!("../completions/fish.txt"),
        "power-shell" => include_str!("../completions/power-shell.txt"),
        "zsh" => include_str!("../completions/zsh.txt"),
        "nushell" => include_str!("../completions/nushell.txt"),
        _ => unreachable!(),
    };
    if let Some(dir) = out_dir {
        let filename = match shell {
            "bash" => "pueue.bash",
            "elvish" => "pueue.elv",
            "fish" => "pueue.fish",
            "power-shell" => "_pueue.ps1",
            "zsh" => "_pueue",
            "nushell" => "pueue.nu",
            _ => unreachable!(),
        };
        let path = Path::new(dir).join(filename);
        if let Err(e) = fs::write(&path, content) {
            // What is original error for completions with invalid output dir? Need to test: ./executable completions bash /nonexistent_dir
            // For now, just print generic
            eprint!("Error: Failed to write completions: {}\n", e);
            return Err(1);
        }
        Ok(0)
    } else {
        print!("{}", content);
        Ok(0)
    }
}

