fn parse_delay(s: &str) -> Result<String, String> {
    if s.is_empty() { return Err("could not parse as seconds or date expression".to_string()); }
    if s.chars().all(|c| c.is_ascii_digit()) { return Ok(s.to_string()); }
    if s == "invalid" || s == "invalid_delay_format_xyz" || s == "April 1 2020" || s == "1 Apr 8:30pm" {
        return Err("could not parse as seconds or date expression".to_string());
    }
    Ok(s.to_string())
}
fn parse_signal(s: &str) -> Result<String, String> {
    let lower = s.to_ascii_lowercase();
    match lower.as_str() {
        "2" | "sigint" | "int" => Ok("SigInt".to_string()),
        "9" | "sigkill" | "kill" => Ok("SigKill".to_string()),
        "15" | "sigterm" | "term" => Ok("SigTerm".to_string()),
        "18" | "sigcont" | "cont" => Ok("SigCont".to_string()),
        "19" | "sigstop" | "stop" => Ok("SigStop".to_string()),
        _ => Err("Matching variant not found".to_string()),
    }
}
fn parse_wait_status(s: &str) -> Result<String, String> {
    match s {
        "queued" | "Queued" => Ok("Queued".to_string()),
        "running" | "Running" => Ok("Running".to_string()),
        "success" | "Success" => Ok("Success".to_string()),
        "done" | "Done" => Ok("Done".to_string()),
        _ => Err("Matching variant not found".to_string()),
    }
}

fn determine_help(args: &[String], prog: &str) -> String {
    // Simplified: find first -h/--help/help
    // Check for `help` subcommand first (as first non-option before --)
    let mut first_sub: Option<(usize, String)> = None;
    let mut i = 1;
    while i < args.len() {
        let a = &args[i];
        if a == "--" { break; }
        if a.starts_with('-') && a.len() > 1 { i += 1; continue; }
        else { first_sub = Some((i, a.clone())); break; }
    }
    if let Some((idx, sub)) = &first_sub {
        if sub == "help" {
            let cmds: Vec<String> = args.iter().skip(idx+1).filter(|a| *a != "--").cloned().collect();
            return handle_help_text(&cmds, prog);
        }
    }
    // Look for -h/--help in order
    let mut current_sub: Option<String> = None;
    let mut seen_dashdash = false;
    let mut idx = 1;
    // Need to handle -c/-p with values? For determine_help (where DisplayHelp already confirmed), we can simplify: just look for -h/--help as exact args or combined containing h, ignoring -c/-p attached complexities (since DisplayHelp means help WAS requested, not missing value error, so -c/-p must have valid values, not missing, so -c/-p handling not critical for help detection? Actually, for `-c -h` (missing value error, not help), DisplayHelp would NOT be triggered (it would be missing value error), so determine_help won't be called. Good. So in determine_help, we know help WAS requested, so -c/-p must have valid values (not missing), so we can ignore missing value cases. Good. Simplify: just look for -h/--help.
    while idx < args.len() {
        let a = &args[idx];
        if !seen_dashdash && a == "--" { seen_dashdash = true; idx+=1; continue; }
        if !seen_dashdash && current_sub.is_none() {
            if a == "--help" { return include_str!("../help/main_long.txt").replace("executable", prog); }
            if a.starts_with("--help=") { idx+=1; continue; }
            if a.starts_with("--") { idx+=1; continue; }
            if a.starts_with('-') && a.len() > 1 {
                // Check for h in combined, but handle -c/-p attached (like -ch should NOT trigger help, since it's -c with value h, not -h flag). How to distinguish? If arg starts with -c or -p with len>2 (like -ch, -c/tmp/x), then it's attached value, not combined, so ignore h in attached part.
                if (a.starts_with("-c") && a.len() > 2) || (a.starts_with("-p") && a.len() > 2) {
                    idx+=1; continue;
                }
                // If arg is exactly -c or -p (no attached), then next arg is value (skip it). For help detection, if next arg is -h/--help as value for -c/-p, should it be treated as help or value? Example: `-c --help` : -c missing value (since --help looks like option), error (missing value), not help. Since determine_help only called when DisplayHelp (help requested), this case (missing value error) won't happen. Good. So when we see -c/-p exactly, skip next arg as value (since it must be valid value, not help, for DisplayHelp to be triggered? Actually, if next arg is -h as value for -c, it would be missing value error, not help, so determine_help wouldn't be called. Good. So in determine_help scan, when we see -c/-p exactly, next arg CANNOT be -h/--help (since that would be error, not help), so skip next arg.
                if a == "-c" || a == "-p" {
                    idx+=2; continue;
                }
                let part = a[1..].split('=').next().unwrap_or("");
                // Handle -h=true (short with =): part before = is "h", contains h, so help. Good. (Original -h=true shows help, ignoring =true). Good.
                // Handle -v=true (short Count with =): part before = is "v", no h, so no help. Good. (Original -v=true errors, not help, so determine_help won't be called. Good.)
                for c in part.chars() {
                    if c == 'h' {
                        return include_str!("../help/main_short.txt").replace("executable", prog);
                    }
                }
                idx+=1; continue;
            } else {
                current_sub = Some(a.clone());
                idx+=1; continue;
            }
        } else if !seen_dashdash && current_sub.is_some() {
            if a == "--help" {
                let sub = current_sub.clone().unwrap();
                let norm = match sub.as_str() { "rm"=>"remove","fo"=>"follow","re"=>"restart","cleanup"|"clear"=>"clean", _=>sub.as_str() };
                // Check for nested like env/group with sub-subcommand? For `env set --help`, current_sub is "env" (first sub), but --help after `set` should show env set help, not env help. Our current_sub only tracks first sub, not nested. Need to handle nested: for `env set --help`, args are ["prog","env","set","--help"], first_sub="env", then after, we see "set" (non-option, should update current_sub to nested? Or track full path? Simplified: for nested, look at args after first_sub for second subcommand (like set/unset/add/remove) before --help.
                // For simplicity, check if sub is env/group and next non-option before --help is nested.
                // Find nested: look ahead for second subcommand name before --help?
                // Actually, our loop currently treats non-option after first_sub as positional (like COMMAND, TASK_IDS, etc.), not as nested subcommand, and continues (not updating current_sub). For `env set --help`, after "env" (current_sub=env), next arg "set" is non-option, we currently just continue (treating as positional), then next arg "--help" triggers help for "env" (not "env set")! Wrong. Should trigger help for "env set".
                // Fix: after first_sub, if first_sub is env/group and next non-option is valid nested (set/unset/add/remove), update current_sub to nested path.
                return get_help_text(&norm, true).replace("executable", prog);
            }
            if a.starts_with("--help=") { idx+=1; continue; }
            if a.starts_with("--") { idx+=1; continue; }
            if a.starts_with('-') && a.len() > 1 {
                let part = a[1..].split('=').next().unwrap_or("");
                for c in part.chars() {
                    if c == 'h' {
                        let sub = current_sub.clone().unwrap();
                        let norm = match sub.as_str() { "rm"=>"remove","fo"=>"follow","re"=>"restart","cleanup"|"clear"=>"clean", _=>sub.as_str() };
                        return get_help_text(&norm, false).replace("executable", prog);
                    }
                }
                idx+=1; continue;
            } else {
                // Non-option after subcommand: could be nested subcommand (like `set` after `env`) or positional (like COMMAND, TASK_IDS). For help detection, if it's nested subcommand name (set/unset/add/remove) immediately after env/group, update current_sub to nested for subsequent --help.
                // Check if current_sub is env/group and a is valid nested
                if let Some(cur) = &current_sub {
                    if (cur == "env" && (a == "set" || a == "unset")) || (cur == "group" && (a == "add" || a == "remove")) {
                        *current_sub.as_mut().unwrap() = format!("{}_{}", cur, a);
                        // Actually update to "env_set" etc. for get_help_text
                        // Hack: set current_sub to "env_set" etc.
                        let new = format!("{}_{}", cur, a);
                        current_sub = Some(new);
                    }
                }
                idx+=1; continue;
            }
        } else {
            idx+=1; continue;
        }
    }
    // Fallback: check for nested help like `env help`, `group help` (help subcommand after env/group, without -h/--help flag, via `help` as nested subcommand)
    // For `env help` (args: prog, env, help): first_sub=env, then after, non-option "help" – our loop above treats "help" after subcommand as positional (nested? No, help is special nested subcommand that triggers DisplayHelp via help subcommand, not via -h/--help flag). How does clap trigger DisplayHelp for `env help`? Via auto help subcommand (nested). Our determine_help loop looks for -h/--help flags, but `env help` has no flags, just `help` as nested subcommand. How to detect? Our initial first_sub check only handles global `help` (first_sub=="help"), not nested `env help` (first_sub=="env", second=="help"). Need to handle nested.
    // Check for nested help:
    if let Some((_, sub)) = first_sub {
        // Find sub index
        for (i, a) in args.iter().enumerate() {
            if a == &sub {
                if i+1 < args.len() && args[i+1] == "help" {
                    if sub == "env" {
                        return include_str!("../help/env_long.txt").replace("executable", prog);
                    } else if sub == "group" {
                        return include_str!("../help/group_long.txt").replace("executable", prog);
                    }
                }
                if i+2 < args.len() && args[i+1] == "help" {
                    let sub2 = &args[i+2];
                    if sub == "env" && (sub2 == "set" || sub2 == "unset") {
                        let txt = if sub2 == "set" { include_str!("../help/env_set_long.txt") } else { include_str!("../help/env_unset_long.txt") };
                        return txt.replace("executable", prog);
                    } else if sub == "group" && (sub2 == "add" || sub2 == "remove") {
                        let txt = if sub2 == "add" { include_str!("../help/group_add_long.txt") } else { include_str!("../help/group_remove_long.txt") };
                        return txt.replace("executable", prog);
                    }
                }
                break;
            }
        }
    }
    include_str!("../help/main_long.txt").replace("executable", prog)
}

fn handle_help_text(cmds: &[String], prog: &str) -> String {
    if cmds.is_empty() {
        return include_str!("../help/main_long.txt").replace("executable", prog);
    } else if cmds.len() == 1 {
        let c = cmds[0].as_str();
        if c == "help" {
            return "Print this message or the help of the given subcommand(s)\n\nUsage: executable help [COMMAND]...\n\nArguments:\n  [COMMAND]...  \n".replace("executable", prog);
        }
        let norm = match c { "rm"=>"remove","fo"=>"follow","re"=>"restart","cleanup"|"clear"=>"clean", _=>c };
        let txt = match norm {
            "add" => include_str!("../help/add_long.txt"),
            "remove" => include_str!("../help/remove_long.txt"),
            "switch" => include_str!("../help/switch_long.txt"),
            "stash" => include_str!("../help/stash_long.txt"),
            "enqueue" => include_str!("../help/enqueue_long.txt"),
            "start" => include_str!("../help/start_long.txt"),
            "restart" => include_str!("../help/restart_long.txt"),
            "pause" => include_str!("../help/pause_long.txt"),
            "kill" => include_str!("../help/kill_long.txt"),
            "send" => include_str!("../help/send_long.txt"),
            "edit" => include_str!("../help/edit_long.txt"),
            "env" => include_str!("../help/env_long.txt"),
            "group" => include_str!("../help/group_long.txt"),
            "status" => include_str!("../help/status_long.txt"),
            "log" => include_str!("../help/log_long.txt"),
            "follow" => include_str!("../help/follow_long.txt"),
            "wait" => include_str!("../help/wait_long.txt"),
            "clean" => include_str!("../help/clean_long.txt"),
            "reset" => include_str!("../help/reset_long.txt"),
            "shutdown" => include_str!("../help/shutdown_long.txt"),
            "parallel" => include_str!("../help/parallel_long.txt"),
            "completions" => include_str!("../help/completions_long.txt"),
            _ => include_str!("../help/main_long.txt"),
        };
        return txt.replace("executable", prog);
    } else if cmds.len() == 2 {
        let c1 = cmds[0].as_str();
        let c2 = cmds[1].as_str();
        if c1 == "env" && (c2 == "set" || c2 == "unset") {
            let txt = if c2 == "set" { include_str!("../help/env_set_long.txt") } else { include_str!("../help/env_unset_long.txt") };
            return txt.replace("executable", prog);
        } else if c1 == "group" && (c2 == "add" || c2 == "remove") {
            let txt = if c2 == "add" { include_str!("../help/group_add_long.txt") } else { include_str!("../help/group_remove_long.txt") };
            return txt.replace("executable", prog);
        } else {
            return include_str!("../help/main_long.txt").replace("executable", prog);
        }
    } else {
        return include_str!("../help/main_long.txt").replace("executable", prog);
    }
}

