        "completions" => {
            let shell = sub_m.get_one::<String>("SHELL").unwrap();
            let out_dir = sub_m.get_one::<String>("OUTPUT_DIRECTORY");
            return handle_completions(shell, out_dir);
        }
        _ => {
            eprintln!("subcommand {} not implemented yet", sub);
            return Err(1);
        }
    }
}

fn handle_completions(shell: &str, out_dir: Option<&String>) -> Result<u8, u8> {
    let content: &str = match shell {
        "bash" => include_str!("../completions/bash.txt"),
        "elvish" => include_str!("../completions/elvish.txt"),
        "fish" => include_str!("../completions/fish.txt"),
        "power-shell" => include_str!("../completions/power-shell.txt"),
        "zsh" => include_str!("../completions/zsh.txt"),
        "nushell" => include_str!("../completions/nushell.txt"),
        _ => unreachable!(),
    };
    if let Some(dir) = out_dir {
        let filename = match shell {
            "bash" => "pueue.bash",
            "elvish" => "pueue.elv",
            "fish" => "pueue.fish",
            "power-shell" => "_pueue.ps1",
            "zsh" => "_pueue",
            "nushell" => "pueue.nu",
            _ => unreachable!(),
        };
        let path = Path::new(dir).join(filename);
        if let Err(e) = fs::write(&path, content) {
            eprint!("Error writing completions: {}\n", e);
            return Err(1);
        }
        Ok(0)
    } else {
        print!("{}", content);
        Ok(0)
    }
}

fn handle_no_subcommand(_global_m: &clap::ArgMatches, _args: &[String], _prog: &str) -> Result<u8, u8> {
    eprintln!("no subcommand not implemented");
    Err(1)
}
