fn deserialize_path_string<'de, D>(deserializer: D) -> Result<Option<PathBuf>, D::Error>
where D: Deserializer<'de> {
    struct PathVisitor;
    impl<'de> serde::de::Visitor<'de> for PathVisitor {
        type Value = Option<PathBuf>;
        fn expecting(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
            write!(f, "path string")
        }
        fn visit_none<E>(self) -> Result<Self::Value, E> where E: serde::de::Error { Ok(None) }
        fn visit_unit<E>(self) -> Result<Self::Value, E> where E: serde::de::Error { Ok(None) }
