// ===== Network helpers =====
use std::io::{Read as IoRead, Write as IoWrite};
use std::net::TcpStream;

fn read_secret(path: &Path) -> Vec<u8> {
    match fs::read(path) {
        Ok(b) => b,
        Err(e) => {
            let msg = format!("I/O error at path \"{}\" while opening secret file. Did you start the daemon at least once?:\n      {}", path.to_string_lossy(), e.to_string());
            print_eyre_error(&[msg], "pueue/src/bin/pueue.rs:91");
        }
    }
}

fn get_data_dir() -> PathBuf {
    if let Ok(xdg) = env::var("XDG_DATA_HOME") {
        if !xdg.is_empty() {
            return PathBuf::from(xdg);
        }
    }
    if let Ok(home) = env::var("HOME") {
        return PathBuf::from(home).join(".local/share");
    }
    PathBuf::from("/root/.local/share")
}

fn default_socket_path() -> PathBuf {
    get_data_dir().join("pueue/pueue_agent.socket")
}
fn default_secret_path() -> PathBuf {
    get_data_dir().join("pueue/shared_secret")
}
fn default_cert_path() -> PathBuf {
    get_data_dir().join("pueue/certs/daemon.cert")
}

fn send_msg(stream: &mut dyn IoWrite, payload: &[u8]) -> Result<(), std::io::Error> {
    let len = payload.len() as u64;
    stream.write_all(&len.to_be_bytes())?;
    stream.write_all(payload)?;
    stream.flush()?;
    Ok(())
}

fn recv_msg(stream: &mut dyn IoRead) -> Result<Vec<u8>, String> {
    let mut hdr = [0u8; 8];
    match stream.read_exact(&mut hdr) {
        Ok(()) => {},
        Err(e) => {
            if e.kind() == std::io::ErrorKind::UnexpectedEof {
                return Err("early eof".to_string());
            } else {
                return Err(e.to_string());
            }
        }
    }
    let len = u64::from_be_bytes(hdr) as usize;
    let mut buf = vec![0u8; len];
    let mut read = 0;
    while read < len {
        match stream.read(&mut buf[read..]) {
            Ok(0) => return Err("early eof".to_string()),
            Ok(n) => read += n,
            Err(e) => return Err(e.to_string()),
        }
    }
    Ok(buf)
}
