// ===== Handshake + Request/Response =====
fn do_handshake(stream: &mut StreamBox, secret: &[u8], verbose: u8, suppress_warn: bool) {
    let is_long = verbose >= 4;
    // Send secret
    let len = secret.len() as u64;
    let mut hdr = len.to_be_bytes().to_vec();
    hdr.extend_from_slice(secret);
    match stream {
        StreamBox::Unix(s) => { let _ = s.write_all(&hdr); let _ = s.flush(); }
        StreamBox::Tcp(s) => { let _ = s.write_all(&hdr); let _ = s.flush(); }
    }
    // Recv version header
    let mut hbuf = [0u8; 8];
    let read_hdr: Result<(), String> = match stream {
        StreamBox::Unix(s) => s.read_exact(&mut hbuf).map_err(|e| {
            if e.kind() == std::io::ErrorKind::UnexpectedEof { "early eof".to_string() } else { e.to_string() }
        }),
        StreamBox::Tcp(s) => s.read_exact(&mut hbuf).map_err(|e| {
            if e.kind() == std::io::ErrorKind::UnexpectedEof { "early eof".to_string() } else { e.to_string() }
        }),
    };
    if let Err(msg) = read_hdr {
        // Failed to receive version during handshake
        if msg == "early eof" {
            // Check if connection closed without any header (early eof)
            let m1 = "Failed to initialize client.".to_string();
            let m2 = "Failed to receive version during handshake with daemon.".to_string();
            let m3 = "I/O error while reading request size header:\n      early eof".to_string();
            print_eyre_error(&[m1, m2, m3], "/workspace/pueue_lib/src/network/client.rs:97");
        } else {
            let m1 = "Failed to initialize client.".to_string();
            let m2 = "Failed to receive version during handshake with daemon.".to_string();
            let m3 = format!("I/O error while reading request size header:\n      {}", msg);
            print_eyre_error(&[m1, m2, m3], "/workspace/pueue_lib/src/network/client.rs:97");
        }
    }
    let vlen = u64::from_be_bytes(hbuf) as usize;
    if vlen == 0 {
        let m1 = "Failed to initialize client.".to_string();
        let m2 = "Daemon went away after sending secret. Did you use the correct secret?".to_string();
        print_eyre_error(&[m1, m2], "/workspace/pueue_lib/src/network/client.rs:99");
    }
    let mut vbuf = vec![0u8; vlen];
    let mut read = 0;
    let read_res: Result<(), String> = (|| {
        while read < vlen {
            let n = match stream {
                StreamBox::Unix(s) => s.read(&mut vbuf[read..]).map_err(|e| e.to_string())?,
                StreamBox::Tcp(s) => s.read(&mut vbuf[read..]).map_err(|e| e.to_string())?,
            };
            if n == 0 {
                return Err("early eof".to_string());
            }
            read += n;
        }
        Ok(())
    })();
    if let Err(msg) = read_res {
        let m1 = "Failed to initialize client.".to_string();
        let m2 = "Failed to receive version during handshake with daemon.".to_string();
        let m3 = format!("I/O error while reading request size header:\n      {}", msg);
        // Actually for payload early eof, is it same location :97? Likely yes (same handshake). Good.
        print_eyre_error(&[m1, m2, m3], "/workspace/pueue_lib/src/network/client.rs:97");
    }
    let version = String::from_utf8_lossy(&vbuf).to_string();
    if version != "4.0.4" {
        if !suppress_warn {
            if is_long {
                log_warn_long("pueue_lib::network::client", &format!("Different protocol version detected '{}'. Consider updating and restarting the daemon.", version), "pueue_lib/src/network/client.rs:111");
            } else {
                // WARN always shown even without -v (verbose 0)? Yes, as observed, WARN shown even with no -v. Good. So always log WARN (short) when version mismatch, regardless of verbose (0-3 short, 4+ long already handled). Good.
                log_warn_short("pueue_lib::network::client", &format!("Different protocol version detected '{}'. Consider updating and restarting the daemon.", version));
            }
        }
    }
}
